//! BPA action types

use crate::sim::ContactId;
use crate::types::{BundleId, NodeId};

/// BPA actions generated by processing
#[derive(Debug, Clone)]
pub enum BpaAction {
    /// Queue bundle for transmission
    QueueForTransmission {
        /// Bundle identifier
        bundle_id: BundleId,
        /// Contact to use for transmission
        contact_id: ContactId,
    },

    /// Deliver bundle to local application
    DeliverLocally {
        /// Bundle to deliver
        bundle_id: BundleId,
    },

    /// Forward bundle to next hop
    Forward {
        /// Bundle to forward
        bundle_id: BundleId,
        /// Destination node
        next_hop: NodeId,
        /// Contact to use
        via_contact: ContactId,
    },

    /// Delete bundle
    Delete {
        /// Bundle to delete
        bundle_id: BundleId,
        /// Deletion reason
        reason: String,
    },

    /// Generate administrative record
    GenerateAdminRecord {
        /// Related bundle
        bundle_id: BundleId,
        /// Record type
        record_type: String,
    },
}

/// Forwarding decision from routing
#[derive(Debug, Clone)]
pub struct ForwardDecision {
    /// Next hop node
    pub next_hop: NodeId,
    /// Contact to use
    pub via_contact: ContactId,
    /// Estimated arrival time
    pub estimated_arrival: Option<crate::types::SimInstant>,
}
